scripts.sync-brands:
node -e 'const fs=require("fs"),path=require("path");const dir=path.join("public","brands");const files=fs.existsSync(dir)?fs.readdirSync(dir).filter(f=>/\.(png|jpe?g|webp|gif|svg)$/i.test(f)&&!f.startsWith(".")).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:"base"})):[];const items=files.map((file,i)=>{const m=file.match(/^(\d+)/);const num=m?String(parseInt(m[1],10)).padStart(2,"0"):String(i+1).padStart(2,"0");const label=file.replace(/\.[^.]+$/,"").replace(/^\d+[_-\s]*/,"").replace(/[_-]+/g," ").trim().toUpperCase()||"BRAND CAMPAIGN";return `  { id: "${num}", src: "/brands/${file}", title: "${num} · ${label}", caption: "Swipe or click to browse campaign visuals" }`;}).join(",
");fs.writeFileSync(path.join("src","data","brandCampaigns.ts"),`export interface BrandCampaignItem {
  id: string;
  src: string;
  title: string;
  caption: string;
}

export const BRAND_CAMPAIGN_ITEMS: BrandCampaignItem[] = [
${items}
];
`,"utf8");console.log("Synced brandCampaigns.ts ("+files.length+" files):",files);'
